//! Core geometric primitives.
//!
//! Mirrors the `Point64` / `PointD` / `Path64` / `Paths64` vocabulary of the
//! C++ library, plus the small set of predicates the clipping and offsetting
//! code is built on.

/// Integer point. Coordinates are 64 bit, exactly as in the C++ original.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub const fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }

    /// Rounds a floating point pair to the nearest integer point.
    ///
    /// `std::round` rounds halves away from zero and so does `f64::round`,
    /// so the two libraries agree on every tie.
    pub fn from_xy(x: f64, y: f64) -> Self {
        Point64 {
            x: round_to_i64(x),
            y: round_to_i64(y),
        }
    }

    pub fn from_pointd(p: PointD) -> Self {
        Point64::from_xy(p.x, p.y)
    }
}

/// Floating point point, used while offsetting before results are rounded.
#[derive(Clone, Copy, PartialEq, Debug, Default)]
pub struct PointD {
    pub x: f64,
    pub y: f64,
}

impl PointD {
    pub const fn new(x: f64, y: f64) -> Self {
        PointD { x, y }
    }

    pub fn from_point64(p: Point64) -> Self {
        PointD {
            x: p.x as f64,
            y: p.y as f64,
        }
    }

    pub fn negated(self) -> Self {
        PointD::new(-self.x, -self.y)
    }
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

/// Axis aligned bounding box.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    pub fn new(left: i64, top: i64, right: i64, bottom: i64) -> Self {
        Rect64 {
            left,
            top,
            right,
            bottom,
        }
    }

    pub fn width(&self) -> i64 {
        self.right - self.left
    }

    pub fn height(&self) -> i64 {
        self.bottom - self.top
    }

    pub fn is_empty(&self) -> bool {
        self.right <= self.left || self.bottom <= self.top
    }
}

pub fn round_to_i64(v: f64) -> i64 {
    if v.is_nan() {
        0
    } else {
        v.round() as i64
    }
}

/// Bounds of a set of paths. Returns `None` when there are no vertices.
pub fn get_bounds(paths: &[Path64]) -> Option<Rect64> {
    let mut r: Option<Rect64> = None;
    for path in paths {
        for p in path {
            r = Some(match r {
                None => Rect64::new(p.x, p.y, p.x, p.y),
                Some(b) => Rect64::new(
                    b.left.min(p.x),
                    b.top.min(p.y),
                    b.right.max(p.x),
                    b.bottom.max(p.y),
                ),
            });
        }
    }
    r
}

/// `(p2 - p1) x (p3 - p2)`, evaluated in 128 bit so it never overflows.
pub fn cross_product(p1: Point64, p2: Point64, p3: Point64) -> i128 {
    let ax = (p2.x - p1.x) as i128;
    let ay = (p2.y - p1.y) as i128;
    let bx = (p3.x - p2.x) as i128;
    let by = (p3.y - p2.y) as i128;
    ax * by - ay * bx
}

pub fn cross_product_d(v1: PointD, v2: PointD) -> f64 {
    v1.x * v2.y - v1.y * v2.x
}

pub fn dot_product_d(v1: PointD, v2: PointD) -> f64 {
    v1.x * v2.x + v1.y * v2.y
}

/// Twice the signed area, in 128 bit. Positive for counter-clockwise paths.
pub fn area2(path: &[Point64]) -> i128 {
    if path.len() < 3 {
        return 0;
    }
    let mut a: i128 = 0;
    let mut prev = path[path.len() - 1];
    for &p in path {
        a += (prev.x as i128 - p.x as i128) * (prev.y as i128 + p.y as i128);
        prev = p;
    }
    -a
}

/// Signed area of a closed path; positive when the path is counter-clockwise.
pub fn area(path: &[Point64]) -> f64 {
    area2(path) as f64 * 0.5
}

pub fn is_positive(path: &[Point64]) -> bool {
    area2(path) > 0
}

/// Unit normal of the edge `pt1 -> pt2`, i.e. the edge direction rotated -90°.
pub fn get_unit_normal(pt1: Point64, pt2: Point64) -> PointD {
    let mut dx = (pt2.x - pt1.x) as f64;
    let mut dy = (pt2.y - pt1.y) as f64;
    if dx == 0.0 && dy == 0.0 {
        return PointD::new(0.0, 0.0);
    }
    let inverse_hypot = 1.0 / (dx * dx + dy * dy).sqrt();
    dx *= inverse_hypot;
    dy *= inverse_hypot;
    PointD::new(dy, -dx)
}

pub fn translate_point(pt: PointD, dx: f64, dy: f64) -> PointD {
    PointD::new(pt.x + dx, pt.y + dy)
}

/// Reflects `pt` through `pivot`.
pub fn reflect_point(pt: PointD, pivot: PointD) -> PointD {
    PointD::new(pivot.x + (pivot.x - pt.x), pivot.y + (pivot.y - pt.y))
}

/// Intersection of the infinite lines through `p1p2` and `p3p4`.
///
/// Parallel lines have no intersection; `p1` is returned so callers degrade to
/// a bevel rather than producing a NaN vertex.
pub fn intersect_point(p1: PointD, p2: PointD, p3: PointD, p4: PointD) -> PointD {
    if p1.x == p2.x {
        // First line vertical.
        if p3.x == p4.x {
            return PointD::new(f64::NAN, f64::NAN);
        }
        let m2 = (p4.y - p3.y) / (p4.x - p3.x);
        let b2 = p3.y - m2 * p3.x;
        return PointD::new(p1.x, m2 * p1.x + b2);
    }
    if p3.x == p4.x {
        // Second line vertical.
        let m1 = (p2.y - p1.y) / (p2.x - p1.x);
        let b1 = p1.y - m1 * p1.x;
        return PointD::new(p3.x, m1 * p3.x + b1);
    }
    let m1 = (p2.y - p1.y) / (p2.x - p1.x);
    let b1 = p1.y - m1 * p1.x;
    let m2 = (p4.y - p3.y) / (p4.x - p3.x);
    let b2 = p3.y - m2 * p3.x;
    if (m1 - m2).abs() > f64::EPSILON {
        let x = (b2 - b1) / (m1 - m2);
        PointD::new(x, m1 * x + b1)
    } else {
        PointD::new(f64::NAN, f64::NAN)
    }
}

/// Drops repeated vertices; when `is_closed_path` also drops a trailing
/// vertex equal to the first one.
pub fn strip_duplicates(path: &mut Path64, is_closed_path: bool) {
    path.dedup();
    if is_closed_path {
        while path.len() > 1 && path[path.len() - 1] == path[0] {
            path.pop();
        }
    }
}

/// Removes vertices that lie on the straight line between their neighbours.
pub fn strip_collinear(path: &Path64) -> Path64 {
    let n = path.len();
    if n < 3 {
        return path.clone();
    }
    let mut out: Path64 = Vec::with_capacity(n);
    for i in 0..n {
        let prev = path[(i + n - 1) % n];
        let curr = path[i];
        let next = path[(i + 1) % n];
        if curr == prev || curr == next {
            continue;
        }
        if cross_product(prev, curr, next) == 0 {
            continue;
        }
        out.push(curr);
    }
    out
}

/// True when `p` lies on the closed segment `a..b`.
pub fn point_on_segment(p: Point64, a: Point64, b: Point64) -> bool {
    if p.x < a.x.min(b.x) || p.x > a.x.max(b.x) || p.y < a.y.min(b.y) || p.y > a.y.max(b.y) {
        return false;
    }
    cross_product(a, b, p) == 0
}

/// Squared distance from `p` to the segment `a..b`, in floating point.
pub fn dist_sqr_point_to_segment(px: f64, py: f64, a: Point64, b: Point64) -> f64 {
    let ax = a.x as f64;
    let ay = a.y as f64;
    let bx = b.x as f64;
    let by = b.y as f64;
    let dx = bx - ax;
    let dy = by - ay;
    let len_sqr = dx * dx + dy * dy;
    if len_sqr <= 0.0 {
        let ex = px - ax;
        let ey = py - ay;
        return ex * ex + ey * ey;
    }
    let mut t = ((px - ax) * dx + (py - ay) * dy) / len_sqr;
    if t < 0.0 {
        t = 0.0;
    } else if t > 1.0 {
        t = 1.0;
    }
    let ex = px - (ax + t * dx);
    let ey = py - (ay + t * dy);
    ex * ex + ey * ey
}

