//!  1. cut every input edge at every point where it meets another edge,
//!  2. keep only those pieces whose two sides disagree about being "inside"
//!     the boolean result, orienting each keeper so the inside is on its left,
//!  3. stitch the survivors back into closed loops.
//!
//! Insideness is decided by winding numbers sampled just off each edge, which
//! keeps the whole thing free of special cases for touching or overlapping
//! geometry.

use crate::core::*;
use std::collections::{HashMap, HashSet};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ClipType {
    NoClip,
    Intersection,
    Union,
    Difference,
    Xor,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

impl FillRule {
    fn is_inside(self, winding: i32) -> bool {
        match self {
            FillRule::EvenOdd => winding % 2 != 0,
            FillRule::NonZero => winding != 0,
            FillRule::Positive => winding > 0,
            FillRule::Negative => winding < 0,
        }
    }
}

/// An input edge, tagged with the polygon set it came from.
#[derive(Clone, Copy)]
struct Edge {
    a: Point64,
    b: Point64,
    is_clip: bool,
}

/// A directed piece of the subdivision.
type Piece = (Point64, Point64);

pub struct Clipper64 {
    subject: Paths64,
    clip: Paths64,
    preserve_collinear: bool,
    reverse_solution: bool,
}

impl Default for Clipper64 {
    fn default() -> Self {
        Self::new()
    }
}

impl Clipper64 {
    pub fn new() -> Self {
        Clipper64 {
            subject: Vec::new(),
            clip: Vec::new(),
            preserve_collinear: true,
            reverse_solution: false,
        }
    }

    pub fn preserve_collinear(&mut self, value: bool) -> &mut Self {
        self.preserve_collinear = value;
        self
    }

    pub fn reverse_solution(&mut self, value: bool) -> &mut Self {
        self.reverse_solution = value;
        self
    }

    pub fn add_subject(&mut self, paths: &[Path64]) -> &mut Self {
        self.subject.extend(paths.iter().cloned());
        self
    }

    pub fn add_clip(&mut self, paths: &[Path64]) -> &mut Self {
        self.clip.extend(paths.iter().cloned());
        self
    }

    pub fn clear(&mut self) {
        self.subject.clear();
        self.clip.clear();
    }

    pub fn execute(&self, clip_type: ClipType, fill_rule: FillRule) -> Paths64 {
        if clip_type == ClipType::NoClip {
            return Vec::new();
        }
        let edges = self.collect_edges();
        if edges.is_empty() {
            return Vec::new();
        }

        let pieces = split_edges_at_crossings(&edges);
        let kept = select_boundary_pieces(&edges, &pieces, clip_type, fill_rule);
        let mut solution = trace_loops(&kept);

        if !self.preserve_collinear {
            solution = solution.into_iter().map(|p| strip_collinear(&p)).collect();
        }
        solution.retain(|p| p.len() >= 3 && area2(p) != 0);

        if self.reverse_solution {
            for p in solution.iter_mut() {
                p.reverse();
            }
        }
        solution
    }

    /// Flattens both polygon sets into a single list of closed-path edges.
    fn collect_edges(&self) -> Vec<Edge> {
        let mut edges = Vec::new();
        for (paths, is_clip) in [(&self.subject, false), (&self.clip, true)] {
            for path in paths {
                let n = path.len();
                if n < 2 {
                    continue;
                }
                for i in 0..n {
                    let a = path[i];
                    let b = path[(i + 1) % n];
                    if a != b {
                        edges.push(Edge { a, b, is_clip });
                    }
                }
            }
        }
        edges
    }
}

/// Keeps the pieces that separate "in" from "out", oriented inside-on-the-left.
fn select_boundary_pieces(
    edges: &[Edge],
    pieces: &[Piece],
    clip_type: ClipType,
    fill_rule: FillRule,
) -> Vec<Piece> {
    let mut kept = Vec::new();
    let mut seen: HashSet<Piece> = HashSet::new();

    for &(a, b) in pieces {
        // Collinear overlaps collapse onto identical pieces; each distinct
        // piece of the subdivision must be considered exactly once.
        let key = if (a.x, a.y) <= (b.x, b.y) {
            (a, b)
        } else {
            (b, a)
        };
        if !seen.insert(key) {
            continue;
        }

        // Midpoints of integer endpoints are exact in binary floating point.
        let mx = (a.x as f64 + b.x as f64) * 0.5;
        let my = (a.y as f64 + b.y as f64) * 0.5;

        // Sampling offset: half the distance to the nearest edge that does not
        // itself pass through the midpoint. Within that radius the winding
        // number is constant on each side of the piece, so the samples cannot
        // land in the wrong region however thin the geometry gets.
        let mut nearest_sqr = f64::INFINITY;
        for e in edges {
            let d = dist_sqr_point_to_segment(mx, my, e.a, e.b);
            if d > 0.0 && d < nearest_sqr {
                nearest_sqr = d;
            }
        }
        let eps = if nearest_sqr.is_finite() {
            nearest_sqr.sqrt() * 0.5
        } else {
            1.0
        };
        if !(eps > 0.0) {
            continue;
        }

        // Unit normal of the piece, pointing to its left.
        let dx = b.x as f64 - a.x as f64;
        let dy = b.y as f64 - a.y as f64;
        let len = (dx * dx + dy * dy).sqrt();
        if len == 0.0 {
            continue;
        }
        let nx = -dy / len;
        let ny = dx / len;

        let left_in = is_inside(mx + nx * eps, my + ny * eps, edges, clip_type, fill_rule);
        let right_in = is_inside(mx - nx * eps, my - ny * eps, edges, clip_type, fill_rule);

        if left_in == right_in {
            continue; // interior edge, or wholly outside: not a boundary
        }
        if left_in {
            kept.push((a, b));
        } else {
            kept.push((b, a));
        }
    }
    kept
}

fn is_inside(
    x: f64,
    y: f64,
    edges: &[Edge],
    clip_type: ClipType,
    fill_rule: FillRule,
) -> bool {
    let (ws, wc) = winding_numbers(x, y, edges);
    let in_subj = fill_rule.is_inside(ws);
    let in_clip = fill_rule.is_inside(wc);
    match clip_type {
        ClipType::Intersection => in_subj && in_clip,
        ClipType::Union => in_subj || in_clip,
        ClipType::Difference => in_subj && !in_clip,
        ClipType::Xor => in_subj != in_clip,
        ClipType::NoClip => false,
    }
}

/// Winding numbers of `(x, y)` with respect to the subject and clip sets.
fn winding_numbers(x: f64, y: f64, edges: &[Edge]) -> (i32, i32) {
    let mut w_subj = 0;
    let mut w_clip = 0;
    for e in edges {
        let ax = e.a.x as f64;
        let ay = e.a.y as f64;
        let bx = e.b.x as f64;
        let by = e.b.y as f64;
        let side = (bx - ax) * (y - ay) - (x - ax) * (by - ay);
        let delta = if ay <= y {
            if by > y && side > 0.0 {
                1
            } else {
                0
            }
        } else if by <= y && side < 0.0 {
            -1
        } else {
            0
        };
        if delta != 0 {
            if e.is_clip {
                w_clip += delta;
            } else {
                w_subj += delta;
            }
        }
    }
    (w_subj, w_clip)
}

/// Cuts every edge at every point where another edge meets it, so that the
/// resulting pieces only ever touch at shared endpoints.
fn split_edges_at_crossings(edges: &[Edge]) -> Vec<Piece> {
    let n = edges.len();
    let mut cuts: Vec<Vec<Point64>> = vec![Vec::new(); n];

    for i in 0..n {
        let (a1, b1) = (edges[i].a, edges[i].b);
        for j in (i + 1)..n {
            let (a2, b2) = (edges[j].a, edges[j].b);

            // Cheap bounding box rejection.
            if a1.x.max(b1.x) < a2.x.min(b2.x)
                || a2.x.max(b2.x) < a1.x.min(b1.x)
                || a1.y.max(b1.y) < a2.y.min(b2.y)
                || a2.y.max(b2.y) < a1.y.min(b1.y)
            {
                continue;
            }

            let d1 = cross_product(a1, b1, a2);
            let d2 = cross_product(a1, b1, b2);
            let d3 = cross_product(a2, b2, a1);
            let d4 = cross_product(a2, b2, b1);

            if d1 != 0 && d2 != 0 && d3 != 0 && d4 != 0 {
                if (d1 > 0) != (d2 > 0) && (d3 > 0) != (d4 > 0) {
                    // Proper crossing: the same rounded point is handed to both
                    // edges so the subdivision stays connected.
                    if let Some(p) = segment_intersection(a1, b1, a2, b2) {
                        cuts[i].push(p);
                        cuts[j].push(p);
                    }
                }
                continue;
            }

            // Touching or collinear-overlapping: split at the shared vertices.
            for &p in &[a2, b2] {
                if point_on_segment(p, a1, b1) {
                    cuts[i].push(p);
                }
            }
            for &p in &[a1, b1] {
                if point_on_segment(p, a2, b2) {
                    cuts[j].push(p);
                }
            }
        }
    }

    let mut pieces = Vec::new();
    for i in 0..n {
        let a = edges[i].a;
        let b = edges[i].b;
        let mut pts = std::mem::take(&mut cuts[i]);
        pts.retain(|&p| p != a && p != b);
        if pts.is_empty() {
            pieces.push((a, b));
            continue;
        }
        // Order the cuts along the edge by distance from its start.
        pts.sort_by(|&p, &q| {
            dist_sqr(a, p)
                .partial_cmp(&dist_sqr(a, q))
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        pts.dedup();

        let mut prev = a;
        for p in pts {
            if p != prev {
                pieces.push((prev, p));
                prev = p;
            }
        }
        if prev != b {
            pieces.push((prev, b));
        }
    }
    pieces
}

fn dist_sqr(a: Point64, b: Point64) -> f64 {
    let dx = b.x as f64 - a.x as f64;
    let dy = b.y as f64 - a.y as f64;
    dx * dx + dy * dy
}

/// Intersection of two properly crossing segments, rounded to the grid.
fn segment_intersection(a1: Point64, b1: Point64, a2: Point64, b2: Point64) -> Option<Point64> {
    let x1 = a1.x as f64;
    let y1 = a1.y as f64;
    let x2 = b1.x as f64;
    let y2 = b1.y as f64;
    let x3 = a2.x as f64;
    let y3 = a2.y as f64;
    let x4 = b2.x as f64;
    let y4 = b2.y as f64;

    let denom = (x2 - x1) * (y4 - y3) - (y2 - y1) * (x4 - x3);
    if denom == 0.0 {
        return None;
    }
    let t = ((x3 - x1) * (y4 - y3) - (y3 - y1) * (x4 - x3)) / denom;
    Some(Point64::from_xy(x1 + t * (x2 - x1), y1 + t * (y2 - y1)))
}

/// Stitches the retained pieces into closed loops.
///
/// At a vertex where several boundary pieces meet, the walk always takes the
/// first outgoing piece clockwise from the one it arrived on, which keeps the
/// filled region on the left throughout and so separates touching loops
/// instead of merging them.
fn trace_loops(kept: &[Piece]) -> Paths64 {
    if kept.is_empty() {
        return Vec::new();
    }

    let mut outgoing: HashMap<Point64, Vec<usize>> = HashMap::new();
    for (idx, &(a, _)) in kept.iter().enumerate() {
        outgoing.entry(a).or_default().push(idx);
    }

    let mut used = vec![false; kept.len()];
    let mut result: Paths64 = Vec::new();

    for start in 0..kept.len() {
        if used[start] {
            continue;
        }
        let start_vertex = kept[start].0;
        let mut loop_pts: Path64 = Vec::new();
        let mut current = start;
        loop {
            used[current] = true;
            let (from, to) = kept[current];
            loop_pts.push(from);

            if to == start_vertex {
                break;
            }
            match next_edge(kept, &outgoing, &used, from, to) {
                Some(next) => current = next,
                None => break,
            }
        }
        if loop_pts.len() >= 3 {
            result.push(loop_pts);
        }
    }
    result
}

fn next_edge(
    kept: &[Piece],
    outgoing: &HashMap<Point64, Vec<usize>>,
    used: &[bool],
    from: Point64,
    at: Point64,
) -> Option<usize> {
    let candidates = outgoing.get(&at)?;
    let ref_angle = ((from.y - at.y) as f64).atan2((from.x - at.x) as f64);

    let mut best: Option<usize> = None;
    let mut best_turn = f64::INFINITY;
    for &idx in candidates {
        if used[idx] {
            continue;
        }
        let target = kept[idx].1;
        let angle = ((target.y - at.y) as f64).atan2((target.x - at.x) as f64);
        // Clockwise sweep starting at the incoming direction; going straight
        // back the way we came is a full turn and so sorts last.
        let mut turn = ref_angle - angle;
        while turn <= 0.0 {
            turn += std::f64::consts::TAU;
        }
        if turn < best_turn {
            best_turn = turn;
            best = Some(idx);
        }
    }
    best
}

/// Boolean union of `subject` with itself under `fill_rule`.
pub fn union_paths(subject: &[Path64], fill_rule: FillRule, preserve_collinear: bool) -> Paths64 {
    let mut c = Clipper64::new();
    c.preserve_collinear(preserve_collinear);
    c.add_subject(subject);
    c.execute(ClipType::Union, fill_rule)
}

/// Boolean intersection of `subject` and `clip`.
pub fn intersect_paths(subject: &[Path64], clip: &[Path64], fill_rule: FillRule) -> Paths64 {
    let mut c = Clipper64::new();
    c.add_subject(subject);
    c.add_clip(clip);
    c.execute(ClipType::Intersection, fill_rule)
}

/// `subject` minus `clip`.
pub fn difference_paths(subject: &[Path64], clip: &[Path64], fill_rule: FillRule) -> Paths64 {
    let mut c = Clipper64::new();
    c.add_subject(subject);
    c.add_clip(clip);
    c.execute(ClipType::Difference, fill_rule)
}

/// Symmetric difference of `subject` and `clip`.
pub fn xor_paths(subject: &[Path64], clip: &[Path64], fill_rule: FillRule) -> Paths64 {
    let mut c = Clipper64::new();
    c.add_subject(subject);
    c.add_clip(clip);
    c.execute(ClipType::Xor, fill_rule)
}

