//! Polygon and polyline offsetting — the `ClipperOffset` half of the library.
//!
//! `InflatePaths` grows (or shrinks, for a negative delta) each input path by
//! `delta`, joining the offset edges according to a [`JoinType`] and capping
//! open paths according to an [`EndType`]. Offsetting alone produces an
//! outline that self-intersects wherever the delta exceeds a local feature
//! size, so the raw outline is finally unioned by [`crate::engine`].

use crate::core::*;
use crate::engine::{ClipType, Clipper64, FillRule};

/// How the outline turns a corner between two offset edges.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum JoinType {
    /// Squares off the corner at exactly `delta` from the original vertex.
    Square,
    /// Straight line between the two offset edge endpoints.
    Bevel,
    /// Circular arc of radius `delta` about the original vertex.
    Round,
    /// Extends both edges to their intersection, falling back to a square
    /// join once that would exceed the miter limit.
    Miter,
}

/// How the ends of a path are treated.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum EndType {
    /// Closed path offset on its outside only.
    Polygon,
    /// Open path offset on both sides, ends joined into a closed loop.
    Joined,
    /// Open path with ends squared off flush with the endpoints.
    Butt,
    /// Open path with ends squared off `delta` beyond the endpoints.
    Square,
    /// Open path with semicircular ends of radius `delta`.
    Round,
}

const DEFAULT_ARC_TOLERANCE: f64 = 0.25;
const FLOATING_POINT_TOLERANCE: f64 = 1.0e-12;

/// One batch of paths sharing a join and end type.
struct Group {
    paths_in: Paths64,
    join_type: JoinType,
    end_type: EndType,
    /// True when the group's outermost path runs clockwise; the delta is
    /// negated for such groups rather than reversing every path.
    is_reversed: bool,
}

impl Group {
    fn new(paths: &[Path64], join_type: JoinType, end_type: EndType) -> Self {
        let is_joined = end_type == EndType::Polygon || end_type == EndType::Joined;
        let mut paths_in: Paths64 = Vec::with_capacity(paths.len());
        for p in paths {
            let mut p = p.clone();
            strip_duplicates(&mut p, is_joined);
            paths_in.push(p);
        }

        let is_reversed = if end_type == EndType::Polygon {
            match lowest_path_idx(&paths_in) {
                Some(idx) => area2(&paths_in[idx]) < 0,
                None => false,
            }
        } else {
            false
        };

        Group {
            paths_in,
            join_type,
            end_type,
            is_reversed,
        }
    }
}

/// Index of the path holding the bottom-most (then left-most) vertex. That
/// path must be an outer one, so its orientation fixes the group's.
fn lowest_path_idx(paths: &[Path64]) -> Option<usize> {
    let mut result = None;
    let mut bot = Point64::new(i64::MAX, i64::MIN);
    for (i, path) in paths.iter().enumerate() {
        if path.len() < 3 {
            continue;
        }
        for &pt in path {
            if pt.y > bot.y || (pt.y == bot.y && pt.x < bot.x) {
                bot = pt;
                result = Some(i);
            }
        }
    }
    result
}

pub struct ClipperOffset {
    groups: Vec<Group>,
    miter_limit: f64,
    arc_tolerance: f64,
    preserve_collinear: bool,
    reverse_solution: bool,

    // Per-group working state.
    delta: f64,
    group_delta: f64,
    abs_group_delta: f64,
    join_type: JoinType,
    end_type: EndType,
    temp_lim: f64,
    steps_per_rad: f64,
    step_sin: f64,
    step_cos: f64,
    norms: Vec<PointD>,
    path_out: Path64,
    solution: Paths64,
}

impl Default for ClipperOffset {
    fn default() -> Self {
        Self::new(2.0, 0.0)
    }
}

impl ClipperOffset {
    pub fn new(miter_limit: f64, arc_tolerance: f64) -> Self {
        ClipperOffset {
            groups: Vec::new(),
            miter_limit,
            arc_tolerance,
            preserve_collinear: false,
            reverse_solution: false,
            delta: 0.0,
            group_delta: 0.0,
            abs_group_delta: 0.0,
            join_type: JoinType::Square,
            end_type: EndType::Polygon,
            temp_lim: 0.0,
            steps_per_rad: 0.0,
            step_sin: 0.0,
            step_cos: 0.0,
            norms: Vec::new(),
            path_out: Vec::new(),
            solution: Vec::new(),
        }
    }

    pub fn miter_limit(&mut self, value: f64) -> &mut Self {
        self.miter_limit = value;
        self
    }

    pub fn arc_tolerance(&mut self, value: f64) -> &mut Self {
        self.arc_tolerance = value;
        self
    }

    pub fn preserve_collinear(&mut self, value: bool) -> &mut Self {
        self.preserve_collinear = value;
        self
    }

    pub fn reverse_solution(&mut self, value: bool) -> &mut Self {
        self.reverse_solution = value;
        self
    }

    pub fn add_path(&mut self, path: &Path64, jt: JoinType, et: EndType) -> &mut Self {
        self.add_paths(std::slice::from_ref(path), jt, et)
    }

    pub fn add_paths(&mut self, paths: &[Path64], jt: JoinType, et: EndType) -> &mut Self {
        if !paths.is_empty() {
            self.groups.push(Group::new(paths, jt, et));
        }
        self
    }

    pub fn clear(&mut self) {
        self.groups.clear();
        self.solution.clear();
    }

    /// Offsets every added group by `delta` and cleans up the result.
    pub fn execute(&mut self, delta: f64) -> Paths64 {
        self.execute_internal(delta);
        if self.solution.is_empty() {
            return Vec::new();
        }
        // Deltas below half a unit round away to nothing; the paths are
        // returned unchanged and need no cleaning.
        if delta.abs() < 0.5 {
            return std::mem::take(&mut self.solution);
        }

        let is_reversed = self.groups[0].is_reversed;
        let fill_rule = if is_reversed {
            FillRule::Negative
        } else {
            FillRule::Positive
        };

        let mut c = Clipper64::new();
        c.preserve_collinear(self.preserve_collinear);
        // The solution should retain the orientation of the input.
        c.reverse_solution(self.reverse_solution != is_reversed);
        c.add_subject(&self.solution);
        c.execute(ClipType::Union, fill_rule)
    }

    fn execute_internal(&mut self, delta: f64) {
        self.solution.clear();
        if self.groups.is_empty() {
            return;
        }

        if delta.abs() < 0.5 {
            for group in &self.groups {
                for path in &group.paths_in {
                    self.solution.push(path.clone());
                }
            }
            return;
        }

        self.temp_lim = if self.miter_limit <= 1.0 {
            2.0
        } else {
            2.0 / (self.miter_limit * self.miter_limit)
        };
        self.delta = delta;

        for i in 0..self.groups.len() {
            self.do_group(i);
        }
    }

    fn do_group(&mut self, group_idx: usize) {
        let paths = std::mem::take(&mut self.groups[group_idx].paths_in);
        for path in &paths {
            self.do_offset(group_idx, path);
        }
        self.groups[group_idx].paths_in = paths;
    }

    fn do_offset(&mut self, group_idx: usize, path: &Path64) {
        self.path_out.clear();
        let cnt = path.len();
        if cnt == 0 {
            return;
        }

        let group_is_reversed = self.groups[group_idx].is_reversed;
        self.group_delta = if group_is_reversed {
            -self.delta
        } else {
            self.delta
        };
        self.abs_group_delta = self.group_delta.abs();
        self.join_type = self.groups[group_idx].join_type;
        self.end_type = self.groups[group_idx].end_type;

        if self.end_type == EndType::Round || self.join_type == JoinType::Round {
            self.calc_round_steps();
        }

        if cnt == 1 {
            self.offset_point_only(path[0]);
            return;
        }

        // A two point "joined" path has no interior to join around.
        if cnt == 2 && self.end_type == EndType::Joined {
            self.end_type = if self.join_type == JoinType::Round {
                EndType::Round
            } else {
                EndType::Square
            };
        }

        self.build_normals(path);

        match self.end_type {
            EndType::Polygon => self.offset_polygon(path),
            EndType::Joined => self.offset_open_joined(path),
            _ => self.offset_open_path(path),
        }
    }

    /// Number of arc segments needed to stay within the arc tolerance.
    fn calc_round_steps(&mut self) {
        if self.abs_group_delta <= FLOATING_POINT_TOLERANCE {
            self.steps_per_rad = 0.0;
            return;
        }
        let arc_tol = if self.arc_tolerance > 0.01 {
            self.arc_tolerance.min(self.abs_group_delta)
        } else {
            (2.0 + self.abs_group_delta).log10() * DEFAULT_ARC_TOLERANCE
        };
        let steps_per_360 = (std::f64::consts::PI / (1.0 - arc_tol / self.abs_group_delta).acos())
            .min(self.abs_group_delta * std::f64::consts::PI);
        let steps_per_360 = if steps_per_360.is_finite() && steps_per_360 > 1.0 {
            steps_per_360
        } else {
            4.0
        };
        let step = std::f64::consts::TAU / steps_per_360;
        self.step_sin = step.sin();
        self.step_cos = step.cos();
        if self.group_delta < 0.0 {
            self.step_sin = -self.step_sin;
        }
        self.steps_per_rad = steps_per_360 / std::f64::consts::TAU;
    }

    fn build_normals(&mut self, path: &Path64) {
        let cnt = path.len();
        self.norms.clear();
        self.norms.reserve(cnt);
        for i in 0..cnt - 1 {
            self.norms.push(get_unit_normal(path[i], path[i + 1]));
        }
        if self.end_type == EndType::Polygon || self.end_type == EndType::Joined {
            self.norms.push(get_unit_normal(path[cnt - 1], path[0]));
        } else {
            self.norms.push(self.norms[cnt - 2]);
        }
    }

    /// A degenerate one vertex path becomes a disc or a square.
    fn offset_point_only(&mut self, pt: Point64) {
        if self.group_delta < 1.0 {
            return;
        }
        self.path_out.clear();
        if self.join_type == JoinType::Round {
            let steps = (self.steps_per_rad * std::f64::consts::TAU).ceil() as i64;
            self.path_out = ellipse(pt, self.abs_group_delta, self.abs_group_delta, steps.max(3));
        } else {
            let d = self.abs_group_delta.ceil() as i64;
            self.path_out = vec![
                Point64::new(pt.x - d, pt.y - d),
                Point64::new(pt.x + d, pt.y - d),
                Point64::new(pt.x + d, pt.y + d),
                Point64::new(pt.x - d, pt.y + d),
            ];
        }
        let out = std::mem::take(&mut self.path_out);
        self.solution.push(out);
    }

    fn offset_polygon(&mut self, path: &Path64) {
        let n = path.len();
        for j in 0..n {
            let k = (j + n - 1) % n;
            self.offset_point(path, j, k);
        }
        let out = std::mem::take(&mut self.path_out);
        self.solution.push(out);
    }

    /// An open path offset on both sides, with the two sides joined into one
    /// closed outline per direction.
    fn offset_open_joined(&mut self, path: &Path64) {
        self.offset_polygon(path);
        let mut reversed = path.clone();
        reversed.reverse();
        self.path_out.clear();
        self.build_normals(&reversed);
        self.offset_polygon(&reversed);
    }

    fn offset_open_path(&mut self, path: &Path64) {
        let high_i = path.len() - 1;

        // Start cap.
        match self.end_type {
            EndType::Butt => {
                let n0 = self.norms[0];
                let d = self.group_delta;
                self.path_out.push(Point64::from_xy(
                    path[0].x as f64 - n0.x * d,
                    path[0].y as f64 - n0.y * d,
                ));
                let p = self.get_perpendic(path[0], n0);
                self.path_out.push(p);
            }
            EndType::Round => self.do_round(path, 0, 0, std::f64::consts::PI),
            _ => self.do_square(path, 0, 0),
        }

        // One side, walking forwards.
        for j in 1..high_i {
            self.offset_point(path, j, j - 1);
        }

        // Flip the normals so they now describe the reverse traversal.
        for i in (1..=high_i).rev() {
            self.norms[i] = self.norms[i - 1].negated();
        }
        self.norms[0] = self.norms[high_i];

        // End cap.
        match self.end_type {
            EndType::Butt => {
                let nh = self.norms[high_i];
                let d = self.group_delta;
                self.path_out.push(Point64::from_xy(
                    path[high_i].x as f64 - nh.x * d,
                    path[high_i].y as f64 - nh.y * d,
                ));
                let p = self.get_perpendic(path[high_i], nh);
                self.path_out.push(p);
            }
            EndType::Round => self.do_round(path, high_i, high_i, std::f64::consts::PI),
            _ => self.do_square(path, high_i, high_i),
        }

        // The other side, walking backwards.
        for j in (1..high_i).rev() {
            self.offset_point(path, j, j + 1);
        }

        let out = std::mem::take(&mut self.path_out);
        self.solution.push(out);
    }

    /// Emits the outline around vertex `j`, arriving along the edge whose
    /// normal is `norms[k]` and leaving along the one with `norms[j]`.
    fn offset_point(&mut self, path: &Path64, j: usize, k: usize) {
        if path[j] == path[k] {
            return;
        }

        let nk = self.norms[k];
        let nj = self.norms[j];
        // sin of the turn angle; its sign says which way the path turns.
        let sin_a = cross_product_d(nk, nj).clamp(-1.0, 1.0);
        let cos_a = dot_product_d(nk, nj);

        if self.abs_group_delta <= FLOATING_POINT_TOLERANCE {
            self.path_out.push(path[j]);
            return;
        }

        if cos_a > -0.99 && sin_a * self.group_delta < 0.0 {
            // Concave: the two offset edges overlap. Emitting both endpoints
            // plus the original vertex leaves a reversed spur that the
            // trailing union reliably removes.
            let p1 = self.get_perpendic(path[j], nk);
            let p2 = self.get_perpendic(path[j], nj);
            self.path_out.push(p1);
            self.path_out.push(path[j]);
            self.path_out.push(p2);
        } else if cos_a > 0.999 && self.join_type != JoinType::Round {
            // Almost straight (under ~2.5 degrees): a miter can never run away.
            self.do_miter(path, j, k, cos_a);
        } else if self.join_type == JoinType::Miter {
            if cos_a > self.temp_lim - 1.0 {
                self.do_miter(path, j, k, cos_a);
            } else {
                self.do_square(path, j, k);
            }
        } else if self.join_type == JoinType::Round {
            self.do_round(path, j, k, sin_a.atan2(cos_a));
        } else if self.join_type == JoinType::Bevel {
            self.do_bevel(path, j, k);
        } else {
            self.do_square(path, j, k);
        }
    }

    fn do_miter(&mut self, path: &Path64, j: usize, k: usize, cos_a: f64) {
        let q = self.group_delta / (cos_a + 1.0);
        let nk = self.norms[k];
        let nj = self.norms[j];
        self.path_out.push(Point64::from_xy(
            path[j].x as f64 + (nk.x + nj.x) * q,
            path[j].y as f64 + (nk.y + nj.y) * q,
        ));
    }

    fn do_bevel(&mut self, path: &Path64, j: usize, k: usize) {
        let (pt1, pt2) = if j == k {
            let nj = self.norms[j];
            let a = self.abs_group_delta;
            (
                PointD::new(path[j].x as f64 - a * nj.x, path[j].y as f64 - a * nj.y),
                PointD::new(path[j].x as f64 + a * nj.x, path[j].y as f64 + a * nj.y),
            )
        } else {
            let nk = self.norms[k];
            let nj = self.norms[j];
            let d = self.group_delta;
            (
                PointD::new(path[j].x as f64 + d * nk.x, path[j].y as f64 + d * nk.y),
                PointD::new(path[j].x as f64 + d * nj.x, path[j].y as f64 + d * nj.y),
            )
        };
        self.path_out.push(Point64::from_pointd(pt1));
        self.path_out.push(Point64::from_pointd(pt2));
    }

    fn do_square(&mut self, path: &Path64, j: usize, k: usize) {
        let nk = self.norms[k];
        let nj = self.norms[j];

        // Unit vector bisecting the corner, pointing away from the path.
        let vec = if j == k {
            PointD::new(nj.y, -nj.x)
        } else {
            normalize_vector(PointD::new(
                -nk.y + nj.y,
                nk.x - nj.x,
            ))
        };
        if vec.x == 0.0 && vec.y == 0.0 {
            self.do_bevel(path, j, k);
            return;
        }

        let abs_delta = self.abs_group_delta;
        let d = self.group_delta;

        // Push the original vertex out along the bisector, then take the line
        // through it perpendicular to the bisector: that line is the squared
        // off corner, and the two offset edges meet it at the join's corners.
        let pt_q = translate_point(
            PointD::from_point64(path[j]),
            abs_delta * vec.x,
            abs_delta * vec.y,
        );
        let pt1 = translate_point(pt_q, d * vec.y, d * -vec.x);
        let pt2 = translate_point(pt_q, d * -vec.y, d * vec.x);
        let pt3 = self.get_perpendic_d(path[k], nk);

        if j == k {
            let pt4 = PointD::new(pt3.x + vec.x * d, pt3.y + vec.y * d);
            let pt = intersect_point(pt1, pt2, pt3, pt4);
            if pt.x.is_nan() || pt.y.is_nan() {
                self.do_bevel(path, j, k);
                return;
            }
            self.path_out.push(Point64::from_pointd(reflect_point(pt, pt_q)));
            self.path_out.push(Point64::from_pointd(pt));
        } else {
            let pt4 = self.get_perpendic_d(path[j], nk);
            let pt = intersect_point(pt1, pt2, pt3, pt4);
            if pt.x.is_nan() || pt.y.is_nan() {
                self.do_bevel(path, j, k);
                return;
            }
            self.path_out.push(Point64::from_pointd(pt));
            self.path_out.push(Point64::from_pointd(reflect_point(pt, pt_q)));
        }
    }

    fn do_round(&mut self, path: &Path64, j: usize, k: usize, angle: f64) {
        if self.steps_per_rad <= 0.0 {
            self.do_bevel(path, j, k);
            return;
        }
        let pt = path[j];
        let nk = self.norms[k];
        let mut offset_vec = PointD::new(nk.x * self.group_delta, nk.y * self.group_delta);
        if j == k {
            offset_vec = offset_vec.negated();
        }
        self.path_out.push(Point64::from_xy(
            pt.x as f64 + offset_vec.x,
            pt.y as f64 + offset_vec.y,
        ));

        let steps = (self.steps_per_rad * angle.abs()).ceil() as i64;
        for _ in 1..steps {
            offset_vec = PointD::new(
                offset_vec.x * self.step_cos - self.step_sin * offset_vec.y,
                offset_vec.x * self.step_sin + offset_vec.y * self.step_cos,
            );
            self.path_out.push(Point64::from_xy(
                pt.x as f64 + offset_vec.x,
                pt.y as f64 + offset_vec.y,
            ));
        }
        let nj = self.norms[j];
        let p = self.get_perpendic(pt, nj);
        self.path_out.push(p);
    }

    fn get_perpendic(&self, pt: Point64, norm: PointD) -> Point64 {
        Point64::from_xy(
            pt.x as f64 + norm.x * self.group_delta,
            pt.y as f64 + norm.y * self.group_delta,
        )
    }

    fn get_perpendic_d(&self, pt: Point64, norm: PointD) -> PointD {
        PointD::new(
            pt.x as f64 + norm.x * self.group_delta,
            pt.y as f64 + norm.y * self.group_delta,
        )
    }
}

fn normalize_vector(vec: PointD) -> PointD {
    let h = (vec.x * vec.x + vec.y * vec.y).sqrt();
    if h <= FLOATING_POINT_TOLERANCE {
        return PointD::new(0.0, 0.0);
    }
    PointD::new(vec.x / h, vec.y / h)
}

/// Polygonal approximation of an ellipse, used for round caps on lone points.
pub fn ellipse(center: Point64, radius_x: f64, radius_y: f64, steps: i64) -> Path64 {
    if radius_x <= 0.0 || radius_y <= 0.0 {
        return Vec::new();
    }
    let steps = if steps < 3 {
        (std::f64::consts::PI * (radius_x + radius_y).sqrt()).ceil().max(3.0) as i64
    } else {
        steps
    };
    let si = (std::f64::consts::TAU / steps as f64).sin();
    let co = (std::f64::consts::TAU / steps as f64).cos();
    let mut dx = co;
    let mut dy = si;
    let mut result = Vec::with_capacity(steps as usize);
    result.push(Point64::from_xy(
        center.x as f64 + radius_x,
        center.y as f64,
    ));
    for _ in 1..steps {
        result.push(Point64::from_xy(
            center.x as f64 + radius_x * dx,
            center.y as f64 + radius_y * dy,
        ));
        let x = dx * co - dy * si;
        dy = dy * co + dx * si;
        dx = x;
    }
    result
}

/// Offsets `paths` by `delta` with the default miter limit and arc tolerance.
pub fn inflate_paths(paths: &[Path64], delta: f64, jt: JoinType, et: EndType) -> Paths64 {
    inflate_paths_with(paths, delta, jt, et, 2.0, 0.0)
}

/// Offsets `paths` by `delta`, with explicit miter limit and arc tolerance.
pub fn inflate_paths_with(
    paths: &[Path64],
    delta: f64,
    jt: JoinType,
    et: EndType,
    miter_limit: f64,
    arc_tolerance: f64,
) -> Paths64 {
    let mut co = ClipperOffset::new(miter_limit, arc_tolerance);
    co.add_paths(paths, jt, et);
    co.execute(delta)
}
